:root{
  --bg:#FAF9F7; --elevated:#FFFFFF; --panel:#F1EFE9; --text:#101010; --text-2:#4C4B47; --text-3:#86847E;
  --border:rgba(16,16,16,.10); --border-strong:rgba(16,16,16,.18); --accent:#14606F; --accent-wash:#EBF3F3;
  --primary-bg:#101010; --primary-fg:#FAF9F7; --confirm:#14601F; --caution:#A86F04; --critical:#B42318;
  --ease-spring:linear(0, 0.046, 0.155, 0.292, 0.434, 0.567, 0.683, 0.779, 0.855, 0.913, 0.955, 0.983, 1.002, 1.013, 1.018, 1.02, 1.019, 1.017, 1.014, 1.012, 1.009, 1.007, 1.005, 1.003, 1); --ease-settle:linear(0, 0.057, 0.18, 0.321, 0.455, 0.573, 0.671, 0.75, 0.812, 0.86, 0.896, 0.924, 0.944, 0.96, 0.971, 0.979, 0.985, 0.989, 0.992, 0.994, 0.996, 0.997, 0.998, 0.999, 1); --ease-pop:linear(0, 0.07, 0.22, 0.4, 0.58, 0.74, 0.87, 0.96, 1.02, 1.045, 1.05, 1.044, 1.034, 1.024, 1.015, 1.008, 1.003, 1);
  --sans:"DM Sans", system-ui, -apple-system, "Segoe UI", sans-serif; --mono:"DM Mono", ui-monospace, Menlo, monospace;
}
@media (prefers-color-scheme: dark){:root:not([data-theme="light"]){
  --bg:#0C0D0F; --elevated:#131417; --panel:#1A1C1F; --text:#F2F1EE; --text-2:#B9B8B4; --text-3:#7F7F7F;
  --border:rgba(255,255,255,.09); --border-strong:rgba(255,255,255,.16); --accent:#7ECAD8; --accent-wash:rgba(126,202,216,.08);
  --primary-bg:#F2F1EE; --primary-fg:#0C0D0F; --confirm:#5EB92D; --caution:#E3A63B; --critical:#F97066; color-scheme:dark}}
:root[data-theme="dark"]{
  --bg:#0C0D0F; --elevated:#131417; --panel:#1A1C1F; --text:#F2F1EE; --text-2:#B9B8B4; --text-3:#7F7F7F;
  --border:rgba(255,255,255,.09); --border-strong:rgba(255,255,255,.16); --accent:#7ECAD8; --accent-wash:rgba(126,202,216,.08);
  --primary-bg:#F2F1EE; --primary-fg:#0C0D0F; --confirm:#5EB92D; --caution:#E3A63B; --critical:#F97066; color-scheme:dark}
*{box-sizing:border-box}
[hidden]{display:none!important}
.arq,.c3-corpo,.bloco,.painel,.visual,.cols,.c1,.tela,.shot{grid-template-columns:minmax(0,1fr)}
.c2,.c3,.m{min-width:0;max-width:100%}
html{-webkit-text-size-adjust:100%}
body{margin:0;background:var(--bg);color:var(--text);font:400 16px/1.55 var(--sans)}
.app{max-width:76rem;margin:0 auto;padding:0 1rem 3rem}
.topo{display:flex;align-items:center;justify-content:space-between;gap:1rem;padding:1.1rem 0;border-bottom:1px solid var(--border)}
.marca{display:flex;align-items:center;gap:.9rem;min-width:0}
.logo{height:22px;width:auto;color:var(--text);flex:none}
.rot{font:400 .75rem/1.3 var(--mono);text-transform:uppercase;letter-spacing:.07em;color:var(--text-3)}
.selo{font:500 .75rem var(--mono);text-transform:uppercase;letter-spacing:.06em;color:var(--caution);border:1px solid currentColor;border-radius:999px;padding:.1rem .55rem;white-space:nowrap}
h1,h2,h3,h4{margin:0;letter-spacing:-.02em;line-height:1.15}
h1{font-size:clamp(2rem,4.6vw,3rem);font-weight:700;letter-spacing:-.03em}
p{margin:0}
code{font-family:var(--mono);font-size:.86em;background:var(--panel);padding:.05rem .3rem;border-radius:4px;overflow-wrap:anywhere}
.ic{width:1em;height:1em;vertical-align:-.14em;flex:none} .ic-lg{width:20px;height:20px;flex:none}
.intro{display:grid;gap:1rem;padding:2.5rem 0 2rem;max-width:46rem}
.intro .lede{font-size:1.1rem;color:var(--text-2)}
.mudou{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1rem;margin:0 0 2.5rem;padding:0;list-style:none}
.mudou li{border-top:1px solid var(--border-strong);padding-top:.6rem;display:grid;gap:.2rem}
.mudou b{font-weight:600} .mudou span{color:var(--text-2);font-size:.93rem}
.area{display:grid;gap:.9rem;margin-bottom:2.2rem}
.area h2{font-size:1.25rem;font-weight:600}
.grade{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1rem}
.card button{all:unset;box-sizing:border-box;cursor:pointer;display:grid;align-content:start;gap:.55rem;height:100%;width:100%;background:var(--elevated);border:1px solid var(--border);border-radius:16px;padding:1.2rem}
.card button:hover{border-color:var(--border-strong)}
.card button:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.card h3{font-size:1.08rem;font-weight:600}
.card-cab{display:flex;gap:.75rem;align-items:center}
.card-cab>div{display:grid;gap:.3rem;justify-items:start}
.av{width:48px;height:48px;border-radius:50%;object-fit:cover;flex:none;box-shadow:0 0 0 1px var(--border-strong)}
.av-lg{width:80px;height:80px}
.av-ini{display:grid;place-items:center;background:var(--accent-wash);color:var(--accent);font:600 .9rem var(--sans)}
.av-lg.av-ini{font-size:1.5rem}
.agente{font-size:.875rem;color:var(--text-2)}
.quem{display:flex;gap:1rem;align-items:center}
.quem>div{display:grid;gap:.25rem}
.card p{color:var(--text-2);font-size:.93rem}
.badge{justify-self:start;font:500 .75rem var(--mono);text-transform:uppercase;letter-spacing:.06em;border:1px solid var(--border-strong);border-radius:999px;padding:.12rem .55rem;color:var(--text-2)}
.n-comecar{color:var(--confirm);border-color:currentColor} .n-estruturar{color:var(--accent);border-color:currentColor} .n-escalar{color:var(--caution);border-color:currentColor}
/* modal */
dialog{border:0;padding:0;margin:0;width:100vw;max-width:100vw;height:100dvh;max-height:100dvh;background:var(--bg);color:var(--text)}
dialog::backdrop{background:rgba(0,0,0,.4)}
.m{max-width:76rem;margin:0 auto;padding:0 1rem 3rem}
.m-topo{position:sticky;top:0;z-index:2;background:var(--bg);display:flex;justify-content:space-between;align-items:center;padding:.9rem 0;border-bottom:1px solid var(--border)}
.fechar{all:unset;cursor:pointer;display:grid;place-items:center;width:36px;height:36px;border-radius:999px;border:1px solid var(--border-strong)}
.fechar:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.c1{display:grid;gap:.8rem;padding:1.8rem 0 1.6rem}
.c1 h2{font-size:clamp(1.6rem,3.4vw,2.3rem);font-weight:700}
.c1 .lede{font-size:1.08rem;color:var(--text-2);max-width:52rem}
.fatos{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1rem;margin:.6rem 0 0}
.fatos div{border-top:1px solid var(--border-strong);padding-top:.5rem;min-width:0}
.fatos dt{font:400 .75rem var(--mono);text-transform:uppercase;letter-spacing:.07em;color:var(--text-3)}
.fatos dd{margin:.25rem 0 0;font-size:.92rem;color:var(--text-2)}
.c2{border:1px solid var(--border);border-radius:16px;background:var(--elevated);padding:1.2rem}
.c2-cab{display:flex;justify-content:space-between;gap:1rem;flex-wrap:wrap;margin-bottom:.8rem}
.fases{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:6px;margin-bottom:1.2rem}
.fases button{all:unset;cursor:pointer;display:grid;gap:.4rem;min-width:0}
.fases i{display:block;height:4px;border-radius:2px;background:var(--border-strong)}
.fases button[aria-selected="true"] i{background:var(--text)}
.fases button.visto i{background:var(--accent)}
.fases span{font:400 .75rem var(--mono);color:var(--text-3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.fases button[aria-selected="true"] span{color:var(--text)}
.fases button:focus-visible{outline:2px solid var(--accent);outline-offset:3px;border-radius:2px}
.tela header{display:grid;gap:.35rem;margin-bottom:1.1rem}
.tela h3{font-size:clamp(1.3rem,2.6vw,1.75rem);font-weight:600}
.corpo{display:grid;grid-template-columns:minmax(0,5fr) minmax(0,7fr);gap:2rem;align-items:start}
.painel,.visual{display:grid;gap:1rem;min-width:0}
.bloco{display:grid;gap:.55rem}
.acoes{list-style:none;margin:0;padding:0;display:grid;gap:.55rem}
.acoes li{display:grid;grid-template-columns:1.6rem minmax(0,1fr);gap:.55rem;align-items:start}
.acoes b.n{display:grid;place-items:center;width:1.6rem;height:1.6rem;border-radius:999px;background:var(--primary-bg);color:var(--primary-fg);font:500 .8rem var(--mono)}
.checks{list-style:none;padding:0;margin:0;display:grid;gap:.45rem}
.checks li{display:flex;gap:.6rem;align-items:flex-start;font-size:.95rem}
.checks input{width:1.05rem;height:1.05rem;margin:.22rem 0 0;accent-color:var(--accent);flex:none}
.checks label{cursor:pointer}
.checks input:checked + label{color:var(--text-3)}
.nota{display:flex;gap:.55rem;align-items:flex-start;font-size:.9rem;color:var(--text-2);background:var(--panel);border-radius:16px;padding:.7rem .85rem}
.nota svg{color:var(--caution);margin-top:.2rem}
.btn{display:inline-flex;align-items:center;gap:.4rem;font:500 .85rem var(--sans);background:var(--primary-bg);color:var(--primary-fg);border:1px solid var(--primary-bg);border-radius:999px;padding:.45rem .95rem;cursor:pointer;white-space:nowrap}
.btn.sec{background:none;color:var(--text);border-color:var(--border-strong)}
.btn:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.passos-nav{display:flex;justify-content:space-between;gap:1rem;margin-top:1.4rem;padding-top:1rem;border-top:1px solid var(--border)}
.arq{border:1px solid var(--border);border-radius:16px;padding:.8rem .9rem;display:grid;gap:.5rem;background:var(--bg);min-width:0}
.arq-cab{display:flex;align-items:center;gap:.6rem;flex-wrap:wrap}
.arq-cab svg{color:var(--accent)}
.arq-nome{display:grid;flex:1 1 10rem;min-width:0}
.arq-nome code{background:none;padding:0;font-size:.9rem;color:var(--text)}
.arq-nome span{font-size:.875rem;color:var(--text-3)}
.ver summary{cursor:pointer;font-size:.85rem;color:var(--text-2)}
pre{max-width:100%;margin:.5rem 0 0;font:400 .875rem/1.5 var(--mono);background:var(--panel);border-radius:8px;padding:.75rem;overflow-x:auto;white-space:pre}
.ok{font-size:.8125rem;color:var(--confirm);min-height:0}
.ok:empty{display:none}
.nome-copia{all:unset;cursor:pointer;display:inline-flex;align-items:center;gap:.35rem;max-width:100%}
.nome-copia code{white-space:normal}
.nome-copia svg{color:var(--text-3)}
.nome-copia:hover svg{color:var(--accent)}
.nome-copia.copiado::after{content:attr(data-ok);font-size:.8125rem;color:var(--confirm);white-space:nowrap}
.nome-copia:focus-visible{outline:2px solid var(--accent);outline-offset:2px;border-radius:4px}
.arvore{background:var(--bg);border:1px solid var(--border);border-radius:16px;padding:1.2rem}
.raiz{display:flex;gap:.55rem;align-items:center;font-weight:600}
.raiz svg,.arvore li>svg{color:var(--accent);width:20px;height:20px;flex:none}
.arvore ul{list-style:none;margin:.8rem 0 0 .6rem;padding:0 0 0 1rem;border-left:1px solid var(--border-strong);display:grid;gap:.8rem}
.arvore li{display:grid;grid-template-columns:20px minmax(0,1fr) auto;gap:.6rem;align-items:start}
.arvore li div{display:grid;gap:.1rem}
.arvore em{font-style:normal;color:var(--text-3);font-size:.875rem}
.tag{font:400 .75rem var(--mono);text-transform:uppercase;letter-spacing:.06em;color:var(--caution);border:1px solid currentColor;border-radius:999px;padding:.05rem .45rem;align-self:center}
.shot{margin:0;display:grid;gap:.4rem}
.shot-img{position:relative;border:1px solid var(--border);border-radius:16px;overflow:hidden;background:#fff;max-width:30rem}
.shot-img img{display:block;width:100%;height:auto}
:root[data-theme="dark"] .shot-img img{filter:brightness(.88)}
@media (prefers-color-scheme: dark){:root:not([data-theme="light"]) .shot-img img{filter:brightness(.88)}}
.pin{position:absolute;border:2px solid #14606F;border-radius:8px;box-shadow:0 0 0 3px rgba(20,96,111,.18)}
.pin b{position:absolute;left:-.7rem;top:-.7rem;display:grid;place-items:center;width:1.4rem;height:1.4rem;border-radius:999px;background:#101010;color:#FAF9F7;font:500 .75rem var(--mono)}
figcaption{font-size:.875rem;color:var(--text-3)}
.cols{display:grid;gap:.6rem}
.col{display:grid;gap:.2rem;border-top:1px solid var(--border);padding-top:.5rem}
.col>code{background:none;padding:0;color:var(--text-3);font-size:.875rem}
.c3{margin-top:1.4rem;border-top:1px solid var(--border)}
.c3 summary{cursor:pointer;list-style:none;display:flex;align-items:center;gap:.5rem;font-weight:600;padding:1rem 0}
.c3 summary::-webkit-details-marker{display:none}
.c3 summary svg{transition:transform .15s var(--ease-settle)}
.c3[open] summary svg{transform:rotate(180deg)}
.c3-corpo{display:grid;gap:.6rem;max-width:56rem;color:var(--text-2)}
.c3-corpo h4{font-size:1rem;font-weight:600;color:var(--text);margin-top:.8rem}
.c3-corpo ul,.c3-corpo ol{margin:0;padding-left:1.2rem;display:grid;gap:.3rem}
.tab{overflow-x:auto}
table{border-collapse:collapse;width:100%;font-size:.88rem}
th,td{text-align:left;padding:.45rem .5rem;border-bottom:1px solid var(--border);vertical-align:top}
th{font:400 .75rem var(--mono);text-transform:uppercase;letter-spacing:.06em;color:var(--text-3)}
footer{margin-top:2rem;padding-top:1rem;border-top:1px solid var(--border);font-size:.875rem;color:var(--text-3)}
@media (max-width:900px){
  .grade,.mudou{grid-template-columns:minmax(0,1fr)}
  .fatos{grid-template-columns:repeat(2,minmax(0,1fr))}
  .corpo{grid-template-columns:minmax(0,1fr)}
  .fases span{font-size:.75rem}
}
@media (max-width:520px){ .fatos{grid-template-columns:minmax(0,1fr)} .fases span{display:none} }
@media (prefers-reduced-motion:reduce){.c3 summary svg{transition:none}}

dialog{width:min(70rem,calc(100vw - 3rem));max-width:none;height:auto;max-height:calc(100dvh - 4rem);margin:auto;border:1px solid var(--border-strong);border-radius:16px;overflow:auto;box-shadow:0 24px 64px rgba(0,0,0,.18)}
dialog::backdrop{background:rgba(16,16,16,.55)}
dialog .m{padding:0 1.6rem 2rem}
dialog .m-topo{margin:0 -1.6rem;padding:.8rem 1.6rem}
.fechar{width:auto;height:auto;display:inline-flex;align-items:center;gap:.4rem;padding:.45rem .95rem;background:var(--primary-bg);color:var(--primary-fg);border-color:var(--primary-bg);font:500 .85rem var(--sans)}
@media (max-width:520px){dialog{width:calc(100vw - 1rem);max-height:calc(100dvh - 1rem);border-radius:16px} dialog .m{padding:0 1rem 1.5rem} dialog .m-topo{margin:0 -1rem;padding:.7rem 1rem}}
.sel-t{display:inline-flex;align-items:center;gap:.35rem;color:var(--confirm)}
.macros{display:flex;flex-wrap:wrap;gap:.5rem;margin:0 0 2.2rem;padding:0;list-style:none}
.macros a{display:inline-block;font:500 .85rem var(--sans);color:var(--text);text-decoration:none;border:1px solid var(--border-strong);border-radius:999px;padding:.3rem .8rem}
.macros a:hover{border-color:var(--text)}
.macro-h{font-size:clamp(1.5rem,3vw,2rem);font-weight:700;margin:1.2rem 0 1.2rem;padding-top:1.2rem;border-top:1px solid var(--border-strong);scroll-margin-top:1rem}
.area h2 .rot{margin-left:.5rem}
.outras-d{margin-top:.2rem;border-top:1px solid var(--border)}
.outras-d>summary{list-style:none;cursor:pointer;display:flex;align-items:center;gap:.5rem;padding:.75rem 0;font-weight:600}
.outras-d>summary::-webkit-details-marker{display:none}
