.outras-d>summary:focus-visible{outline:2px solid var(--accent);outline-offset:2px;border-radius:4px}
.outras-nota{font-size:.88rem;color:var(--text-2);margin:0 0 .8rem}
.minis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:.7rem}
.mini button{all:unset;box-sizing:border-box;cursor:pointer;display:grid;align-content:start;gap:.45rem;height:100%;width:100%;background:var(--elevated);border:1px solid var(--border);border-radius:16px;padding:.85rem}
