const ARQ = JSON.parse(document.getElementById('arquivos').textContent);
const PRINTS = JSON.parse(document.getElementById('prints').textContent);
const caixa = document.querySelector('.m');
function fechar(){ try { parent.postMessage({ tessGuia: 'fechar' }, '*'); } catch (e) {} }
caixa.querySelectorAll('img[data-print]').forEach(im => im.src = PRINTS[im.dataset.print]);
document.addEventListener('keydown', e => { if (e.key === 'Escape') fechar(); });
function ligarPassos(){
  const abas = [...caixa.querySelectorAll('.fases button')], telas = [...caixa.querySelectorAll('.tela')];
  const ant = caixa.querySelector('.ant'), prox = caixa.querySelector('.prox');
  let i = 0;
  function ir(n){
    abas[i].classList.add('visto');
    i = Math.max(0, Math.min(telas.length - 1, n));
    telas.forEach((t, k) => t.hidden = k !== i);
    abas.forEach((a, k) => a.setAttribute('aria-selected', String(k === i)));
    ant.disabled = i === 0; prox.hidden = i === telas.length - 1;
    caixa.querySelector('.c2').scrollIntoView({block: 'start', behavior: matchMedia('(prefers-reduced-motion:reduce)').matches ? 'auto' : 'smooth'});
  }
  abas.forEach((a, k) => a.addEventListener('click', () => ir(k)));
  ant.addEventListener('click', () => ir(i - 1)); prox.addEventListener('click', () => ir(i + 1));
  ant.disabled = true;
  caixa.querySelector('.fechar').addEventListener('click', fechar);
}
async function copiar(t){
  try { if (navigator.clipboard && isSecureContext) { await navigator.clipboard.writeText(t); return true; } } catch (e) {}
  const ta = document.createElement('textarea'); ta.value = t; ta.setAttribute('readonly', '');
  ta.style.position = 'fixed'; ta.style.left = '-9999px'; document.body.appendChild(ta); ta.select();
  let ok = false; try { ok = document.execCommand('copy'); } catch (e) {}
  ta.remove(); return ok;
}
function avisar(el, txt){
  const ok = el.closest('.arq')?.querySelector('.ok');
  if (!ok) { el.dataset.ok = txt; el.classList.add('copiado'); setTimeout(() => { el.classList.remove('copiado'); delete el.dataset.ok; }, 1800); return; }
  ok.textContent = txt; setTimeout(() => ok.textContent = '', 2200);
}
document.addEventListener('click', async e => {
  const c = e.target.closest('[data-copiar]'), b = e.target.closest('[data-baixar]');
  if (c) { const ok = await copiar(ARQ[c.dataset.copiar][1]); avisar(c, ok ? 'Copiado' : 'Selecione e use Cmd+C ou Ctrl+C'); }
  if (b) {
    const [nome, txt] = ARQ[b.dataset.baixar];
    const url = URL.createObjectURL(new Blob([txt], {type: 'text/plain;charset=utf-8'}));
    const a = document.createElement('a'); a.href = url; a.download = nome; document.body.appendChild(a); a.click(); a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000); avisar(b, 'Baixado: ' + nome);
  }
});

ligarPassos();
